CREATE TABLE AFFIXFILE_${_parameter} ( OBJECTID SERIAL primary key, CONTENT bytea DEFAULT NULL, OBJGUID varchar(64) DEFAULT NULL );
CREATE TABLE AFFIXTABLE_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, TYPE varchar(128) NOT NULL, AFFIXFILEID varchar(256) DEFAULT NULL );
CREATE TABLE TEXTURES_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, FORMAT integer DEFAULT NULL, MAGFILTER integer DEFAULT NULL, MINFILTER integer DEFAULT NULL, WRAPS integer DEFAULT NULL, WRAPT integer DEFAULT NULL, IMAGENAME varchar(128) DEFAULT NULL, TEXIMGID varchar(128) DEFAULT NULL );
CREATE TABLE TEXIMG_${_parameter} ( OBJECTID SERIAL primary key, CONTENT bytea DEFAULT NULL, OBJGUID varchar(64) DEFAULT NULL );
CREATE TABLE TILESETTABLE_${_parameter} ( OBJECTID SERIAL primary key, PARENT int DEFAULT NULL, MINX real DEFAULT NULL, MINY real DEFAULT NULL, MINZ real DEFAULT NULL, MAXX real DEFAULT NULL, MAXY real DEFAULT NULL, MAXZ real DEFAULT NULL, CENTER varchar(128) DEFAULT NULL, LASTUPDATETIME varchar(128) DEFAULT NULL );
CREATE TABLE GEOTABLE_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, TILESETID int DEFAULT -1, MATRIX varchar(512) DEFAULT NULL, MESHIDS text DEFAULT NULL, BLOCKID int DEFAULT NULL, BOX text DEFAULT NULL, FAMILYID int DEFAULT NULL );
CREATE TABLE GEOBLOCK_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, DESCRIBE varchar(128) DEFAULT NULL, MESHIDS text DEFAULT NULL );
CREATE TABLE FAMILYTABLE_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, PARENTID int NOT NULL, DESCRIBE varchar(128) DEFAULT NULL );
CREATE TABLE FMYITEMTABLE_${_parameter} ( OBJECTID SERIAL primary key, SECTION varchar(128) DEFAULT NULL, NAME varchar(128) DEFAULT NULL, VALUE varchar(256) DEFAULT NULL, UNIT varchar(128) DEFAULT NULL, TYPE int DEFAULT NULL, FAMILYID int DEFAULT NULL ); CREATE TABLE PROTABLE_${_parameter} ( OBJECTID SERIAL primary key, SECTION varchar(128) DEFAULT NULL, NAME varchar(128) DEFAULT NULL, VALUE varchar(256) DEFAULT NULL, UNIT varchar(128) DEFAULT NULL, TYPE int DEFAULT NULL, GEOID int DEFAULT NULL ); CREATE TABLE MESHTABLE_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, MATERIALID int DEFAULT NULL, ACCESSOR_POSTION int DEFAULT NULL, ACCESSOR_INDEX int DEFAULT NULL, ACCESSOR_NORMAL int DEFAULT NULL, ACCESSOR_TEXCOORD_0 int DEFAULT NULL, ACCESSOR_TEXCOORD_1 int DEFAULT NULL, ACCESSOR_TEXCOORD_2 int DEFAULT NULL, ACCESSOR_TEXCOORD_3 int DEFAULT NULL, ACCESSOR_TEXCOORD_4 int DEFAULT NULL, ACCESSOR_TEXCOORD_5 int DEFAULT NULL, ACCESSOR_TEXCOORD_6 int DEFAULT NULL, ACCESSOR_TEXCOORD_7 int DEFAULT NULL );
CREATE TABLE ACCESSORTABLE_${_parameter} ( OBJECTID SERIAL primary key, TYPE varchar(128) DEFAULT NULL, BYTEOFFSET int DEFAULT NULL, BYTESTRIDE int DEFAULT NULL, COMPONENTTYPE int DEFAULT NULL, NCOUNT int DEFAULT NULL, BFILEID varchar(128) DEFAULT NULL ); CREATE TABLE BFILETABLE_${_parameter} ( OBJECTID SERIAL primary key, CONTENT bytea DEFAULT NULL, OBJGUID varchar(64) DEFAULT NULL ); CREATE TABLE MATERIALTABLE_${_parameter} ( OBJECTID SERIAL primary key, NAME varchar(128) DEFAULT NULL, TECHDES varchar(128) DEFAULT NULL, AMBIENT varchar(128) DEFAULT NULL, EMISSION varchar(128) DEFAULT NULL, SHININESS varchar(128) DEFAULT NULL, SPECULAR varchar(128) DEFAULT NULL, DIFFUSE varchar(128) DEFAULT NULL, TEXTURE_1 int DEFAULT NULL, TEXTURE_2 int DEFAULT NULL, TEXTURE_3 int DEFAULT NULL, TEXTURE_4 int DEFAULT NULL );

CREATE TABLE if not exists PROJECT ( OBJECTID SERIAL PRIMARY KEY NOT NULL, NAME varchar(128) DEFAULT NULL, PREFIXION int NOT NULL, SOURCEID int DEFAULT -1, DESCRIBE varchar(128) DEFAULT NULL, FOREIGNID varchar(128) DEFAULT NULL, ZIPKEY varchar(128) DEFAULT NULL, ZIPPATH varchar(256) DEFAULT NULL, WORKSPACEID int DEFAULT NULL );
CREATE TABLE if not exists COORDINATE_SYSTEM ( OBJECTID SERIAL PRIMARY KEY NOT NULL, NAME varchar(128) DEFAULT NULL, SEMIMAJORAXIS real DEFAULT NULL, INVERSEFLATTENING real DEFAULT NULL, SCALEFACTOR real DEFAULT NULL, FALSE_EASTING real DEFAULT NULL, FALSE_NORTHING real DEFAULT NULL, CENTRALMERIDIAN real DEFAULT NULL );
CREATE TABLE if not exists T_USER ( USER_ID serial PRIMARY KEY NOT NULL, USER_NAME varchar(128) DEFAULT NULL, USER_REAL_NAME varchar(128) DEFAULT NULL, PASSWORD varchar(128) DEFAULT NULL, LAST_IP varchar(128) DEFAULT NULL, LAST_VISIT varchar(128) DEFAULT NULL );
CREATE TABLE if not exists WORKSPACE( OBJECTID SERIAL primary key, NAME varchar(128) NOT NULL, CODE varchar(128) DEFAULT NULL, USERID varchar(128) NOT NULL, DESCRIBE varchar(128) DEFAULT NULL );
